# sre_error_budget.py - runnable; SLO/SLI/error-budget calculator + burn-rate alerter
from dataclasses import dataclass
from datetime import datetime, timedelta

@dataclass
class SLOConfig:
    slo: float                  # e.g. 0.999 for 99.9%
    window_days: int = 30       # rolling window

    def error_budget_ratio(self) -> float:
        return 1.0 - self.slo

    def budget_seconds(self) -> float:
        return self.error_budget_ratio() * self.window_days * 86400

    def budget_minutes(self) -> float:
        return self.budget_seconds() / 60

@dataclass
class BurnRateAlert:
    threshold: float            # multiplier on sustainable burn
    window_minutes: int
    page: bool                  # True = page, False = ticket

def evaluate_sli(good: int, total: int, cfg: SLOConfig) -> dict:
    if total == 0:
        return {"sli": 1.0, "breach": False, "budget_remaining_ratio": 1.0}
    sli = good / total
    budget_used_ratio = max(0.0, (cfg.slo - sli) / cfg.error_budget_ratio())
    budget_remaining_ratio = max(0.0, 1.0 - budget_used_ratio)
    return {
        "sli": round(sli, 6),
        "slo": cfg.slo,
        "breach": sli < cfg.slo,
        "budget_used_pct": round(budget_used_ratio * 100, 2),
        "budget_remaining_pct": round(budget_remaining_ratio * 100, 2),
    }

def burn_rate(errors_last_window: int, total_last_window: int, cfg: SLOConfig) -> float:
    """Burn rate = observed error rate / sustainable error rate."""
    if total_last_window == 0:
        return 0.0
    observed_error_rate = errors_last_window / total_last_window
    sustainable_error_rate = cfg.error_budget_ratio()
    return observed_error_rate / sustainable_error_rate

def alert_for_burn(burn: float, alerts: list[BurnRateAlert]) -> list[str]:
    fired = []
    for a in alerts:
        if burn >= a.threshold:
            kind = "PAGE" if a.page else "TICKET"
            fired.append(f"{kind}: burn={burn:.1f}x >= {a.threshold}x over {a.window_minutes}m")
    return fired

if __name__ == "__main__":
    cfg = SLOConfig(slo=0.999, window_days=30)
    print(f"Error budget: {cfg.budget_minutes():.1f} min / {cfg.window_days}d")

    # last 1h: 50,000 requests, 8 errors  -> burn = ?
    burn_1h = burn_rate(8, 50_000, cfg)
    print(f"1h burn: {burn_1h:.2f}x (sustainable=1x)")

    alerts = [
        BurnRateAlert(threshold=14.0, window_minutes=60, page=True),
        BurnRateAlert(threshold=6.0,  window_minutes=60, page=False),
        BurnRateAlert(threshold=3.0,  window_minutes=360, page=False),
    ]
    for f in alert_for_burn(burn_1h, alerts):
        print("  " + f)

    # monthly evaluation
    print(evaluate_sli(good=4_396_210, total=4_400_000, cfg=cfg))
